// P11 browser check: loads a single-player save holding a running 4-side battle (generated by
// p11-sp-save.ts) into the real client and checks the battle HUD from a participant's perspective and from
// a spectator's, plus the strategic PvP relation panel. Needs `npm run dev` on 5173.
// usage: node scripts/combat/p11-browser.cjs <save.json> [outDir]
const { chromium } = require('playwright');
const fs = require('fs');
const [savePath, outDir = 'artifacts/p11'] = process.argv.slice(2);
const data = JSON.parse(fs.readFileSync(savePath, 'utf8'));
(async () => {
  fs.mkdirSync(outDir, { recursive: true });
  const browser = await chromium.launch({ args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const report = { checks: [], errors: [] };
  const check = (ok, label, extra) => { report.checks.push({ ok: !!ok, label, ...(extra ? { extra } : {}) }); console.log(ok ? 'PASS' : 'FAIL', label, extra ? JSON.stringify(extra) : ''); };
  async function open(token, viewport) {
    const page = await browser.newPage({ viewport, deviceScaleFactor: 1 });
    page.on('pageerror', e => report.errors.push(e.message));
    page.on('dialog', d => d.dismiss());
    await page.addInitScript(([save, token]) => { localStorage.setItem('siderarium.sp.v1', save); localStorage.setItem('siderarium.sp.token', token); }, [JSON.stringify(data.save), token]);
    await page.goto('http://127.0.0.1:5173/?sp=continue&name=P11', { waitUntil: 'domcontentloaded' });
    await page.waitForFunction(() => window.siderarium?.hud && window.siderarium.client.state, null, { timeout: 60000 });
    return page;
  }
  try {
    // --- participant (알파 PMC) ---
    const page = await open(data.token, { width: 1440, height: 900 });
    const me = await page.evaluate(() => window.siderarium.client.company);
    check(me === data.me, 'single-player client resumes as 알파 PMC', { me });
    const eng = await page.evaluate(() => { const st = window.siderarium.client.state; return Object.values(st.engagements).find(e => !e.done && e.sides.length === 4)?.id; });
    check(!!eng, 'the 4-side battle is still running after the save is loaded', { eng });
    // strategic PvP panel: select a 브라보 ship
    const pvp = await page.evaluate(([B]) => {
      const app = window.siderarium, st = app.client.state;
      const s = Object.values(st.ships).find(x => x.owner === B);
      app.hud.select({ kind: 'ship', id: s.id });
      const txt = document.body.innerText;
      return { hostile: /관계:\s*적대/.test(txt), stanceBtns: document.querySelectorAll('[data-stance]').length, pvpBtn: document.querySelectorAll('[data-pvp]').length };
    }, [Object.keys(data.companies)[1]]);
    check(pvp.hostile && pvp.stanceBtns >= 1, 'strategic info for a 브라보 ship shows the relation 적대 and stance actions', pvp);
    await page.screenshot({ path: `${outDir}/strategic-pvp.png` });
    await page.evaluate(id => window.siderarium.hud.opts.onOpenBattle(id), eng);
    await page.waitForSelector('#sides', { timeout: 30000 });
    await page.waitForTimeout(1500);
    const hud = await page.evaluate(() => {
      const t = s => document.querySelector(s)?.innerText ?? '';
      return { sides: t('#sides'), tree: t('#treeBody'), left: t('#sal'), right: t('#sel'), withdraw: !!document.querySelector('#battleWithdraw') };
    });
    check(/찰리 PMC/.test(hud.sides) && /동맹/.test(hud.sides) && /브라보 PMC/.test(hud.sides) && /델타 PMC/.test(hud.sides) && /적대/.test(hud.sides), 'side panel lists every side with its relation to 알파 (own/ally/enemy)', { sides: hud.sides });
    const order = ['알파', '찰리', '브라보', '델타'].map(n => hud.tree.indexOf(n));
    check(order.every(i => i >= 0) && order[0] < order[1] && order[1] < order[2], 'command tree is grouped own → ally → enemy', { order });
    check(hud.withdraw, 'participant sees the "전 함대 철수" button');
    check(/아군|자사|우군/.test(hud.left) || hud.left.length > 0, 'strength labels present', { left: hud.left, right: hud.right });
    await page.screenshot({ path: `${outDir}/battle-participant-1440.png` });
    await page.setViewportSize({ width: 390, height: 844 });
    await page.waitForTimeout(800);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 1);
    check(!overflow, 'battle HUD has no horizontal page scroll at 390px');
    await page.screenshot({ path: `${outDir}/battle-participant-390.png` });
    // let it run a little, no page errors
    await page.waitForTimeout(3000);
    await page.close();
    // --- spectator (a company not in the battle) ---
    const sp = await open(data.specToken, { width: 1440, height: 900 });
    await sp.evaluate(id => window.siderarium.hud.opts.onOpenBattle(id), eng);
    await sp.waitForSelector('#sides', { timeout: 30000 });
    await sp.waitForTimeout(1500);
    const sh = await sp.evaluate(() => ({ sides: document.querySelector('#sides')?.innerText ?? '', withdraw: !!document.querySelector('#battleWithdraw'), right: document.querySelector('#sel')?.innerText }));
    check(!/동맹|적대|자사/.test(sh.sides) && ['알파', '브라보', '찰리', '델타'].every(n => sh.sides.includes(n)), 'spectator sees all four sides by name with no forced relation labels', sh);
    check(!sh.withdraw, 'spectator gets no withdraw button');
    await sp.screenshot({ path: `${outDir}/battle-spectator-1440.png` });
    await sp.close();
  } catch (e) { report.errors.push(String(e && e.stack || e)); }
  finally {
    fs.writeFileSync(`${outDir}/browser-results.json`, JSON.stringify(report, null, 2));
    await browser.close();
  }
  const failed = report.checks.filter(c => !c.ok).length;
  console.log(JSON.stringify({ passed: report.checks.length - failed, failed, errors: report.errors }, null, 2));
  if (failed || report.errors.length) process.exitCode = 1;
})();
